struct Failure:std::runtime_error {std::string code;Failure(const char*c,const std::string&m):runtime_error(m),code(c){}};
static void require(bool ok,const char*code,const std::string&m){if(!ok)throw Failure(code,m);}
static uint64_t limit=0,used=0,peak=0;
struct alignas(std::max_align_t) Allocation{size_t bytes;};
static void* alloc(size_t n){if(uint64_t(n)>limit-used||n>SIZE_MAX-sizeof(Allocation))return nullptr;auto*p=(Allocation*)std::malloc(sizeof(Allocation)+n);if(!p)return nullptr;p->bytes=n;used+=n;if(used>peak)peak=used;return p+1;}
static void release(void*p){if(p){auto*h=((Allocation*)p)-1;used-=h->bytes;std::free(h);}}
template<class T>struct Alloc {using value_type=T;Alloc()=default;template<class U>Alloc(const Alloc<U>&){} T*allocate(size_t n){if(n>SIZE_MAX/sizeof(T))throw std::bad_alloc();auto*p=alloc(n*sizeof(T));if(!p)throw std::bad_alloc();return(T*)p;}void deallocate(T*p,size_t){release(p);}};
template<class T>using Vec=std::vector<T,Alloc<T>>;
struct Buffer{void*p=nullptr;size_t size=0;Buffer()=default;explicit Buffer(uint64_t n){require(n<=SIZE_MAX,"E_DEEP_ADDRESS","Allocation exceeds host address domain");size=size_t(n);if(size){p=alloc(size);require(p,"E_DEEP_BUDGET","Decode memory budget exceeded");std::memset(p,0,size);}}~Buffer(){release(p);}Buffer(Buffer&&b)noexcept:p(b.p),size(b.size){b.p=nullptr;}Buffer&operator=(Buffer&&b)noexcept{release(p);p=b.p;size=b.size;b.p=nullptr;return*this;}Buffer(const Buffer&)=delete;};
static std::string lastError;
static void errorCb(exr_const_context_t,exr_result_t,const char*msg){lastError=msg?msg:"OpenEXRCore failure";}
static void check(exr_result_t result){if(result!=EXR_ERR_SUCCESS)throw Failure(result==EXR_ERR_OUT_OF_MEMORY?"E_DEEP_BUDGET":"E_DEEP_FILE",lastError.empty()?exr_get_default_error_message(result):lastError);}
static uint64_t number(const std::string&s){require(!s.empty()&&s.find_first_not_of("0123456789")==std::string::npos,"E_DEEP_ARGUMENT","Unsigned integer argument required");size_t at=0;auto n=std::stoull(s,&at);require(at==s.size(),"E_DEEP_ARGUMENT","Unsigned integer argument required");return n;}
static std::string quote(const std::string&s){std::string out="\"";const char*h="0123456789abcdef";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=c;}else if(c<32){out+="\\u00";out+=h[c>>4];out+=h[c&15];}else out+=c;}return out+'"';}
static std::string real(double n,int precision=17){require(std::isfinite(n),"E_DEEP_METADATA","Nonfinite supported metadata value");std::ostringstream o;o<<std::setprecision(precision)<<n;return o.str();}
static std::string hex(const char*p,size_t n){const char*h="0123456789abcdef";std::string out;out.reserve(n*2);for(size_t i=0;i<n;i++){auto c=(unsigned char)p[i];out+=h[c>>4];out+=h[c&15];}return out;}
static uint64_t mul(uint64_t a,uint64_t b){require(!a||b<=UINT64_MAX/a,"E_DEEP_ADDRESS","Size multiplication overflow");return a*b;}
struct Context{exr_context_t c=nullptr;~Context(){if(c)exr_finish(&c);}};
struct Decode{exr_const_context_t c;exr_decode_pipeline_t d=EXR_DECODE_PIPELINE_INITIALIZER;Decode(exr_const_context_t c_,int part,const exr_chunk_info_t&i):c(c_){check(exr_decoding_initialize(c,part,&i,&d));}~Decode(){exr_decoding_destroy(c,&d);}};
struct Chunk{exr_chunk_info_t info;int32_t x,y;};
struct Verify{uint32_t*counts;uint32_t width;Chunk chunk;};
static exr_result_t verifyCounts(exr_decode_pipeline_t*p){auto*v=(Verify*)p->decoding_user_data;for(int32_t y=0;y<p->chunk.height;y++)for(int32_t x=0;x<p->chunk.width;x++)if(p->sample_count_table[uint64_t(y)*p->chunk.width+x]<0||uint32_t(p->sample_count_table[uint64_t(y)*p->chunk.width+x])!=v->counts[uint64_t(v->chunk.y+y)*v->width+v->chunk.x+x])return EXR_ERR_INVALID_SAMPLE_DATA;return EXR_ERR_SUCCESS;}
static std::string box(const exr_attr_box2i_t&b){return"["+std::to_string(b.min.x)+","+std::to_string(b.min.y)+","+std::to_string(b.max.x)+","+std::to_string(b.max.y)+"]";}
static int run(const std::vector<std::string>&args){
 require(args.size()==10,"E_DEEP_ARGUMENT","input output part maxPixels maxSamples maxSamplesPerPixel maxMemory maxParts maxChannels required");
 uint64_t part=number(args[2]),maxPixels=number(args[3]),maxSamples=number(args[4]),maxPixelSamples=number(args[5]),maxParts=number(args[7]),maxChannels=number(args[8]);
 // The last argument is an explicit format-contract version.
 require(number(args[9])==1,"E_DEEP_VERSION","Decoder contract version1 required");limit=number(args[6]);require(limit&&maxPixels&&maxParts&&maxChannels&&maxPixelSamples,"E_DEEP_BUDGET","Explicit positive budgets required");
 Context ctx;exr_context_initializer_t init=EXR_DEFAULT_CONTEXT_INITIALIZER;init.alloc_fn=alloc;init.free_fn=release;init.error_handler_fn=errorCb;init.flags=EXR_CONTEXT_FLAG_STRICT_HEADER|EXR_CONTEXT_FLAG_DISABLE_CHUNK_RECONSTRUCTION;
 check(exr_start_read(&ctx.c,args[0].c_str(),&init));int parts=0;check(exr_get_count(ctx.c,&parts));require(parts>0&&uint64_t(parts)<=maxParts&&part<uint64_t(parts)&&part<=INT32_MAX,"E_DEEP_PART","Part selection or budget invalid");
 exr_storage_t storage;check(exr_get_storage(ctx.c,int(part),&storage));require(storage==EXR_STORAGE_DEEP_SCANLINE||storage==EXR_STORAGE_DEEP_TILED,"E_DEEP_PROFILE","Selected part is not deep scanline/tiled");
 exr_attr_box2i_t dw,display;check(exr_get_data_window(ctx.c,int(part),&dw));check(exr_get_display_window(ctx.c,int(part),&display));int64_t width=int64_t(dw.max.x)-dw.min.x+1,height=int64_t(dw.max.y)-dw.min.y+1;require(width>0&&height>0&&width<=INT32_MAX&&height<=INT32_MAX,"E_DEEP_WINDOW","Invalid data window");uint64_t pixels=mul(width,height);require(pixels<=maxPixels&&pixels<=SIZE_MAX/8-1,"E_DEEP_BUDGET","Pixel budget exceeded");
 const exr_attr_chlist_t*channels=nullptr;check(exr_get_channels(ctx.c,int(part),&channels));require(channels->num_channels>0&&uint64_t(channels->num_channels)<=maxChannels,"E_DEEP_CHANNELS","Channel budget exceeded");uint64_t sampleBytes=0;for(int i=0;i<channels->num_channels;i++){auto&ch=channels->entries[i];require(ch.x_sampling==1&&ch.y_sampling==1,"E_DEEP_PROFILE","Deep subsampled channels are unsupported");require(ch.pixel_type==EXR_PIXEL_HALF||ch.pixel_type==EXR_PIXEL_FLOAT||ch.pixel_type==EXR_PIXEL_UINT,"E_DEEP_PROFILE","Unknown channel type");sampleBytes+=ch.pixel_type==EXR_PIXEL_HALF?2:4;}
 int32_t tileWidth=0,tileHeight=0;Vec<Chunk> chunks;int32_t nChunks=0;check(exr_get_chunk_count(ctx.c,int(part),&nChunks));require(nChunks>0&&uint64_t(nChunks)<=pixels,"E_DEEP_CHUNKS","Invalid chunk count");chunks.reserve(nChunks);
 if(storage==EXR_STORAGE_DEEP_SCANLINE){for(int64_t y=dw.min.y;y<=dw.max.y;){Chunk c{};check(exr_read_scanline_chunk_info(ctx.c,int(part),int(y),&c.info));require(c.info.width==width&&c.info.height>0&&c.info.start_y==y&&y+c.info.height<=int64_t(dw.max.y)+1,"E_DEEP_CHUNKS","Invalid scanline geometry");c.x=0;c.y=int32_t(y-dw.min.y);chunks.push_back(c);y+=c.info.height;}}
 else{int32_t lx,ly,nx,ny,tw,th;check(exr_get_tile_levels(ctx.c,int(part),&lx,&ly));require(lx==1&&ly==1,"E_DEEP_PROFILE","Deep tiled v1 accepts one level; no implicit mip selection");check(exr_get_tile_counts(ctx.c,int(part),0,0,&nx,&ny));check(exr_get_tile_sizes(ctx.c,int(part),0,0,&tw,&th));tileWidth=tw;tileHeight=th;require(nx>0&&ny>0&&tw>0&&th>0&&uint64_t(nx)*ny==uint64_t(nChunks),"E_DEEP_CHUNKS","Invalid tile geometry");for(int32_t ty=0;ty<ny;ty++)for(int32_t tx=0;tx<nx;tx++){Chunk c{};check(exr_read_tile_chunk_info(ctx.c,int(part),tx,ty,0,0,&c.info));require(int64_t(tx)*tw<width&&int64_t(ty)*th<height,"E_DEEP_CHUNKS","Tile origin outside the data window");c.x=int32_t(int64_t(tx)*tw);c.y=int32_t(int64_t(ty)*th);require(c.info.width>0&&c.info.height>0&&int64_t(c.x)+c.info.width<=width&&int64_t(c.y)+c.info.height<=height,"E_DEEP_CHUNKS","Invalid clipped tile geometry");chunks.push_back(c);}}
 require(chunks.size()==uint64_t(nChunks),"E_DEEP_CHUNKS","Chunk count disagrees with selected window");Buffer countStorage(mul(pixels,4)),offsetStorage(mul(pixels+1,8));auto*counts=(uint32_t*)countStorage.p;auto*offsets=(uint64_t*)offsetStorage.p;uint64_t total=0;
 for(auto&chunk:chunks){Decode decoder(ctx.c,int(part),chunk.info);auto&d=decoder.d;d.decode_flags=EXR_DECODE_SAMPLE_COUNTS_AS_INDIVIDUAL|EXR_DECODE_SAMPLE_DATA_ONLY;check(exr_decoding_choose_default_routines(ctx.c,int(part),&d));check(exr_decoding_run(ctx.c,int(part),&d));uint64_t sum=0;for(int32_t y=0;y<chunk.info.height;y++)for(int32_t x=0;x<chunk.info.width;x++){int32_t n=d.sample_count_table[uint64_t(y)*chunk.info.width+x];require(n>=0&&uint64_t(n)<=maxPixelSamples&&total<=maxSamples&&uint64_t(n)<=maxSamples-total,"E_DEEP_SAMPLES","Sample count budget exceeded");counts[(chunk.y+y)*width+chunk.x+x]=uint32_t(n);total+=uint32_t(n);sum+=uint32_t(n);}require(mul(sum,sampleBytes)==chunk.info.unpacked_size,"E_DEEP_CHUNKS","Sample count and unpacked pixel byte size disagree");}
 for(uint64_t i=0;i<pixels;i++)offsets[i+1]=offsets[i]+counts[i];require(offsets[pixels]==total,"E_DEEP_SAMPLES","Inconsistent counts");Vec<Buffer> planes;for(int i=0;i<channels->num_channels;i++)planes.emplace_back(mul(total,channels->entries[i].pixel_type==EXR_PIXEL_HALF?2:4));
 for(auto&chunk:chunks){uint64_t localSamples=0;for(int32_t y=0;y<chunk.info.height;y++)for(int32_t x=0;x<chunk.info.width;x++)localSamples+=counts[(chunk.y+y)*width+chunk.x+x];Decode decoder(ctx.c,int(part),chunk.info);auto&d=decoder.d;d.decode_flags=EXR_DECODE_SAMPLE_COUNTS_AS_INDIVIDUAL;Vec<Buffer> tmp;for(int i=0;i<d.channel_count;i++){auto&ch=d.channels[i];tmp.emplace_back(mul(localSamples,ch.bytes_per_element));ch.decode_to_ptr=(uint8_t*)tmp.back().p;ch.user_bytes_per_element=ch.bytes_per_element;ch.user_data_type=ch.data_type;ch.user_pixel_stride=ch.bytes_per_element;require(uint64_t(width)*ch.bytes_per_element<=INT32_MAX,"E_DEEP_ADDRESS","Chunk stride exceeds library address domain");ch.user_line_stride=int32_t(width)*ch.bytes_per_element;}
 Verify verify{counts,uint32_t(width),chunk};d.decoding_user_data=&verify;d.realloc_nonimage_data_fn=verifyCounts;check(exr_decoding_choose_default_routines(ctx.c,int(part),&d));check(exr_decoding_run(ctx.c,int(part),&d));uint64_t local=0;for(int32_t y=0;y<chunk.info.height;y++)for(int32_t x=0;x<chunk.info.width;x++){uint64_t pixel=(chunk.y+y)*width+chunk.x+x,n=counts[pixel];for(int i=0;i<d.channel_count;i++){size_t bpe=d.channels[i].bytes_per_element;if(n)std::memcpy((uint8_t*)planes[i].p+offsets[pixel]*bpe,(uint8_t*)tmp[i].p+local*bpe,n*bpe);}local+=n;}}
 std::string attrs="{",unknown="[";bool hasAttrs=false,hasUnknown=false;int32_t attributeCount=0;check(exr_get_attribute_count(ctx.c,int(part),&attributeCount));
 for(int32_t i=0;i<attributeCount;i++){const exr_attribute_t*a=nullptr;check(exr_get_attribute_by_index(ctx.c,int(part),EXR_ATTR_LIST_FILE_ORDER,i,&a));std::string n=a->name;if(n=="channels"||n=="compression"||n=="dataWindow"||n=="displayWindow"||n=="type"||n=="name"||n=="chunkCount"||n=="version"||n=="tiles")continue;std::string v;bool known=true;
  if(a->type==EXR_ATTR_FLOAT)v=real(a->f,9);else if(a->type==EXR_ATTR_DOUBLE)v=real(a->d);else if(a->type==EXR_ATTR_INT)v=std::to_string(a->i);else if(a->type==EXR_ATTR_STRING)v=quote(hex(a->string->str,a->string->length));else if(a->type==EXR_ATTR_V2F)v="["+real(a->v2f->x,9)+","+real(a->v2f->y,9)+"]";else if(a->type==EXR_ATTR_LINEORDER||a->type==EXR_ATTR_DEEP_IMAGE_STATE)v=std::to_string(a->uc);else if(a->type==EXR_ATTR_CHROMATICITIES){auto*c=a->chromaticities;v="["+real(c->red_x,9)+","+real(c->red_y,9)+","+real(c->green_x,9)+","+real(c->green_y,9)+","+real(c->blue_x,9)+","+real(c->blue_y,9)+","+real(c->white_x,9)+","+real(c->white_y,9)+"]";}else known=false;
  if(known){if(hasAttrs)attrs+=',';hasAttrs=true;attrs+=quote(n)+":{\"type\":"+quote(a->type_name)+",\"value\":"+v+"}";}else{if(hasUnknown)unknown+=',';hasUnknown=true;unknown+="{\"name\":"+quote(n)+",\"type\":"+quote(a->type_name)+"}";}}
 attrs+='}';unknown+=']';const char*name=nullptr;check(exr_get_name(ctx.c,int(part),&name));exr_compression_t compression;check(exr_get_compression(ctx.c,int(part),&compression));std::string json="{\"version\":1,\"library\":\"OpenEXRCore-3.4.4\",\"part\":"+std::to_string(part)+",\"partCount\":"+std::to_string(parts)+",\"name\":"+quote(name?name:"")+",\"storage\":"+quote(storage==EXR_STORAGE_DEEP_TILED?"deep-tiled":"deep-scanline")+",\"compression\":"+std::to_string(compression)+",\"dataWindow\":"+box(dw)+",\"displayWindow\":"+box(display)+",\"width\":"+std::to_string(width)+",\"height\":"+std::to_string(height)+",\"pixels\":"+std::to_string(pixels)+",\"samples\":"+std::to_string(total)+",\"channels\":[";
 for(int i=0;i<channels->num_channels;i++){auto&ch=channels->entries[i];if(i)json+=',';json+="{\"name\":"+quote(ch.name.str)+",\"type\":"+quote(ch.pixel_type==EXR_PIXEL_HALF?"half":ch.pixel_type==EXR_PIXEL_FLOAT?"float":"uint")+",\"pLinear\":"+(ch.p_linear?"true":"false")+"}";}
 json+="],\"attributes\":"+attrs+",\"unsupportedAttributes\":"+unknown+",\"tileWidth\":"+std::to_string(tileWidth)+",\"tileHeight\":"+std::to_string(tileHeight)+",\"decoderPeakAllocatedBytes\":"+std::to_string(peak)+"}";require(json.size()<=UINT32_MAX,"E_DEEP_BUDGET","Metadata budget exceeded");uint64_t payload=pixels*4;for(auto&plane:planes)payload+=(plane.size+3)/4*4;
 std::ofstream output(std::filesystem::u8path(args[1]),std::ios::binary|std::ios::trunc);require(bool(output),"E_DEEP_IO","Cannot create private decoder output");uint32_t jsonBytes=uint32_t(json.size()),version=1;output.write("FWDEEP01",8);output.write((char*)&jsonBytes,4);output.write((char*)&version,4);output.write((char*)&payload,8);output.write(json.data(),json.size());char zero[8]={};output.write(zero,(8-json.size()%8)%8);output.write((char*)counts,pixels*4);for(auto&plane:planes){if(plane.size)output.write((char*)plane.p,plane.size);output.write(zero,(4-plane.size%4)%4);}output.close();require(bool(output),"E_DEEP_IO","Private output write failed");std::cout<<"{\"ok\":true,\"metadata\":"<<json<<"}\n";return 0;
}
static int entry(const std::vector<std::string>&args){try{return run(args);}catch(const Failure&e){std::cout<<"{\"ok\":false,\"code\":"<<quote(e.code)<<",\"message\":"<<quote(e.what())<<"}\n";}catch(const std::bad_alloc&){std::cout<<"{\"ok\":false,\"code\":\"E_DEEP_BUDGET\",\"message\":\"Decode allocation budget exceeded\"}\n";}catch(const std::exception&e){std::cout<<"{\"ok\":false,\"code\":\"E_DEEP_FILE\",\"message\":"<<quote(e.what())<<"}\n";}return 1;}
#ifdef _WIN32
int wmain(int argc,wchar_t**argv){std::vector<std::string>args;for(int i=1;i<argc;i++){int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,argv[i],-1,nullptr,0,nullptr,nullptr);if(n<=0)return 2;std::string s(n,0);WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,argv[i],-1,s.data(),n,nullptr,nullptr);s.pop_back();args.push_back(s);}return entry(args);}
#else
int main(int argc,char**argv){return entry(std::vector<std::string>(argv+1,argv+argc));}
#endif
